import js from "@eslint/js"
import importPlugin from "eslint-plugin-import"
import unicorn from "eslint-plugin-unicorn"
import tseslint from "typescript-eslint"
import { ambientAuthority, invariants, swallowedCause, uninstalledSafety } from "../../../../eslint.invariants.js"
import { jsdocConvention } from "../../../../eslint.jsdoc.js"

export default tseslint.config(
  {
    ignores: ["**/dist", "**/build", "**/coverage"]
  },
  js.configs.recommended,
  importPlugin.flatConfigs.recommended,
  importPlugin.flatConfigs.typescript,
  {
    files: ["src/**/*.ts", "examples/**/*.ts"],
    extends: [tseslint.configs.recommended],
    languageOptions: {
      parserOptions: {
        project: "./tsconfig.test.json",
        tsconfigRootDir: import.meta.dirname
      }
    },
    settings: {
      "import/resolver": {
        typescript: {
          project: ["./tsconfig.json"]
        }
      }
    },
    plugins: {
      unicorn
    },
    rules: {
      "@typescript-eslint/array-type": ["error", { default: "generic", readonly: "generic" }],
      "@typescript-eslint/consistent-type-imports": ["error", { fixStyle: "inline-type-imports" }],
      "@typescript-eslint/no-explicit-any": "off",
      "@typescript-eslint/no-import-type-side-effects": "error",
      "@typescript-eslint/no-unnecessary-type-assertion": "error",
      "@typescript-eslint/no-unnecessary-type-constraint": "error",
      "@typescript-eslint/no-unused-vars": ["error", { argsIgnorePattern: "^_", varsIgnorePattern: "^_" }],
      "@typescript-eslint/no-useless-empty-export": "error",
      "import/no-duplicates": "error",
      "import/no-empty-named-blocks": "error",
      "import/no-self-import": "error",
      "no-await-in-loop": "off",
      "no-console": "error",
      "no-fallthrough": "off",
      "no-shadow": "off",
      "no-unneeded-ternary": "error",
      "no-unused-vars": "off",
      "no-useless-concat": "error",
      "no-useless-constructor": "error",
      "no-var": "error",
      "object-shorthand": "off",
      "require-yield": "off",
      "unicorn/no-abusive-eslint-disable": "error",
      "unicorn/no-accessor-recursion": "error",
      "unicorn/prefer-array-flat-map": "error"
    }
  },
  ...jsdocConvention,
  ...invariants(uninstalledSafety, swallowedCause, ambientAuthority)
)

{
  "name": "@smthrs/evals",
  "type": "module",
  "version": "1.0.0-rc.16",
  "license": "MIT",
  "smthrs": {
    "group": "agent"
  },
  "description": "Fixed-suite evaluation, baselines, regression reports, and score gates for flows",
  "homepage": "https://github.com/smithersai/smithers",
  "repository": {
    "type": "git",
    "url": "https://github.com/smithersai/smithers.git",
    "directory": "packages/smithers/agent/evals"
  },
  "bugs": {
    "url": "https://github.com/smithersai/smithers/issues"
  },
  "tags": [
    "typescript",
    "effect",
    "flow",
    "evaluation"
  ],
  "keywords": [
    "typescript",
    "effect",
    "flow",
    "evaluation"
  ],
  "engines": {
    "node": ">=22.19.0"
  },
  "sideEffects": [],
  "exports": {
    "./package.json": "./package.json",
    ".": "./src/index.ts",
    "./internal/*": null,
    "./*/index": null,
    "./Baseline": "./src/Baseline.ts",
    "./CaseExecutor": "./src/CaseExecutor.ts",
    "./EvalError": "./src/EvalError.ts",
    "./Gate": "./src/Gate.ts",
    "./Regression": "./src/Regression.ts",
    "./Report": "./src/Report.ts",
    "./Runner": "./src/Runner.ts",
    "./Suite": "./src/Suite.ts",
    "./Trials": "./src/Trials.ts",
    "./index": "./src/index.ts"
  },
  "files": [
    "src/**/*.ts",
    "dist/**/*.js",
    "dist/**/*.js.map",
    "dist/**/*.d.ts",
    "dist/**/*.d.ts.map",
    "dist/**/package.json",
    "LICENSE",
    "README.md",
    "CHANGELOG.md",
    "docs/"
  ],
  "publishConfig": {
    "access": "public",
    "provenance": true,
    "tag": "next",
    "exports": {
      "./package.json": "./package.json",
      ".": {
        "import": {
          "types": "./dist/esm/index.d.ts",
          "default": "./dist/esm/index.js"
        },
        "require": {
          "types": "./dist/cjs/index.d.ts",
          "default": "./dist/cjs/index.js"
        }
      },
      "./internal/*": null,
      "./*/index": null,
      "./Baseline": {
        "import": {
          "types": "./dist/esm/Baseline.d.ts",
          "default": "./dist/esm/Baseline.js"
        },
        "require": {
          "types": "./dist/cjs/Baseline.d.ts",
          "default": "./dist/cjs/Baseline.js"
        }
      },
      "./CaseExecutor": {
        "import": {
          "types": "./dist/esm/CaseExecutor.d.ts",
          "default": "./dist/esm/CaseExecutor.js"
        },
        "require": {
          "types": "./dist/cjs/CaseExecutor.d.ts",
          "default": "./dist/cjs/CaseExecutor.js"
        }
      },
      "./EvalError": {
        "import": {
          "types": "./dist/esm/EvalError.d.ts",
          "default": "./dist/esm/EvalError.js"
        },
        "require": {
          "types": "./dist/cjs/EvalError.d.ts",
          "default": "./dist/cjs/EvalError.js"
        }
      },
      "./Gate": {
        "import": {
          "types": "./dist/esm/Gate.d.ts",
          "default": "./dist/esm/Gate.js"
        },
        "require": {
          "types": "./dist/cjs/Gate.d.ts",
          "default": "./dist/cjs/Gate.js"
        }
      },
      "./Regression": {
        "import": {
          "types": "./dist/esm/Regression.d.ts",
          "default": "./dist/esm/Regression.js"
        },
        "require": {
          "types": "./dist/cjs/Regression.d.ts",
          "default": "./dist/cjs/Regression.js"
        }
      },
      "./Report": {
        "import": {
          "types": "./dist/esm/Report.d.ts",
          "default": "./dist/esm/Report.js"
        },
        "require": {
          "types": "./dist/cjs/Report.d.ts",
          "default": "./dist/cjs/Report.js"
        }
      },
      "./Runner": {
        "import": {
          "types": "./dist/esm/Runner.d.ts",
          "default": "./dist/esm/Runner.js"
        },
        "require": {
          "types": "./dist/cjs/Runner.d.ts",
          "default": "./dist/cjs/Runner.js"
        }
      },
      "./Suite": {
        "import": {
          "types": "./dist/esm/Suite.d.ts",
          "default": "./dist/esm/Suite.js"
        },
        "require": {
          "types": "./dist/cjs/Suite.d.ts",
          "default": "./dist/cjs/Suite.js"
        }
      },
      "./Trials": {
        "import": {
          "types": "./dist/esm/Trials.d.ts",
          "default": "./dist/esm/Trials.js"
        },
        "require": {
          "types": "./dist/cjs/Trials.d.ts",
          "default": "./dist/cjs/Trials.js"
        }
      },
      "./index": {
        "import": {
          "types": "./dist/esm/index.d.ts",
          "default": "./dist/esm/index.js"
        },
        "require": {
          "types": "./dist/cjs/index.d.ts",
          "default": "./dist/cjs/index.js"
        }
      }
    }
  },
  "scripts": {
    "lint": "eslint src examples --max-warnings=0 && dprint check",
    "format": "dprint fmt",
    "build": "node scripts/build.mjs",
    "check": "vibelang -b tsconfig.json && vibelang -p tsconfig.test.json --noEmit",
    "circular": "node ../../../repo-targets/scripts/circular.mjs",
    "test": "vitest",
    "coverage": "vitest --coverage"
  },
  "dependencies": {
    "@smthrs/core": "1.0.0-rc.16",
    "@smthrs/scorers": "1.0.0-rc.16",
    "devalue": "5.9.2"
  },
  "peerDependencies": {
    "effect": "4.0.5"
  },
  "devDependencies": {
    "@effect/language-service": "0.87.2",
    "@eslint/js": "9.39.5",
    "@types/node": "26.4.1",
    "@vitest/coverage-v8": "5.0.0",
    "dprint": "0.57.1",
    "effect": "4.0.5",
    "esbuild": "0.28.2",
    "eslint": "9.39.5",
    "eslint-import-resolver-typescript": "4.4.5",
    "eslint-plugin-import": "2.32.0",
    "eslint-plugin-jsdoc": "64.3.4",
    "eslint-plugin-unicorn": "65.0.0",
    "madge": "8.0.0",
    "typescript": "5.9.3",
    "typescript-eslint": "8.69.0",
    "vibelang": "0.0.8",
    "vibelang-vite": "0.0.8",
    "vitest": "5.0.0"
  }
}

import { tmpdir } from "node:os"
import { join } from "node:path"
import { fileURLToPath } from "node:url"
import vibelang from "vibelang-vite"
import { configDefaults, defineConfig } from "vitest/config"

export default defineConfig({
  plugins: [vibelang({ project: "tsconfig.test.json" })],
  test: {
    globalSetup: [
      fileURLToPath(new URL("../../../repo-targets/test-utils/coverage-teardown.mjs", import.meta.url)),
      fileURLToPath(new URL("../../../repo-targets/test-utils/test-process-environment.mjs", import.meta.url))
    ],
    include: [...configDefaults.include, "**/*.{test,spec}.vibe"],
    environment: "node",
    // House convention (see packages/smithers/flows/journal/vitest.config.ts): a finite 30 s
    // wall-clock budget so correct suites survive coverage-instrumented load
    // while a genuine hang still fails the run.
    testTimeout: 30_000,
    hookTimeout: 30_000,
    coverage: {
      enabled: true,
      provider: "v8",
      // Per-process report directory so concurrent vitest runs do not destroy
      // each other's coverage scratch state (issues #115/#121).
      reportsDirectory: join(tmpdir(), `flows-evals-coverage-${process.pid}`),
      include: ["src/**"],
      thresholds: {
        branches: 100,
        functions: 100,
        lines: 100,
        statements: 100
      }
    }
  }
})
